{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "상담사가 '어차피'가 보통 뭐라고 말하느냐고 질문한 것은 내담자가 대화에서 드러낸 '원래 이런 걸 못 하는 사람', '역시 나는 안 되는구나'라는 핵심 신념의 내용을 구체화하려는 것이므로, 이 진술이 직접적으로 관련됨. 조부모·부모의 양육 방식에서 형성된 성장 배경이 그 신념의 기원을 설명함."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '막힌 상태에 앉아 있으면 바보가 된 것 같아서 못 견디겠다'고 한 것은 '답답한 것을 참고 하는 것은 불가능에 가까운 고통'이라는 태도와 일치하며, 과제 시작 후 유튜브로 도피한 상황 사례가 그 태도가 실제 행동으로 이어진 예시임."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/0"],
      "relevance": "'어차피'의 내용은 '억지로 붙잡고 앉아 있어도 집중 안 되고 괴롭기만 할 뿐'이라는 부정적 가정과 정확히 부합하며, 내담자가 '개요 짜다 막히면 답답해져서 못 견디겠다'고 한 진술이 이 가정이 작동하는 장면을 보여줌."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '새벽에 하면 더 집중 잘 된다'고 합리화한 것은 '불편한 기분을 달래면 나중에 컨디션이 좋아졌을 때 해낼 수 있다'는 긍정적 가정의 실제 발현이며, 상황 사례 0의 자동적 사고와 일치함."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '하기 싫어지면 여기서 나가야 한다'는 급함을 몸으로 느끼고, 어릴 때 피아노 앞에서도 같은 급함을 느꼈다고 한 것은 '기분이 내키지 않으면 시작할 수 없고, 하기 싫어지면 미루거나 넘어가야 한다'는 규칙이 어릴 때부터 작동해 왔음을 보여줌."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '계획 세우는 것까진 잘하는데 단 한 번도 지켜본 적이 없다'고 한 것은 자기통제·자기훈련의 부족이라는 초기 도식과 직접 연결되며, 조부모·부모가 계속하도록 붙잡지 않은 성장 경험이 그 도식의 형성 배경임."
    },
    {
      "trait_id": "/core_belief/young_domain",
      "background_ids": ["/childhood_data"],
      "relevance": "'손상된 한계' 영역은 내담자가 불편한 감정을 견디는 한계를 스스로 설정하지 못하고 회피를 선택하는 패턴과 관련되며, 성장 배경에서 '하기 싫으면 그만해도 된다'는 환경이 그 한계 설정 기회를 차단했음을 보여줌."
    },
    {
      "trait_id": "/coping_strategies/0",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '유튜브 하나만 보고 리프레시하자'고 시작한 영상이 새벽 3시까지 이어진다고 직접 서술한 것은 이 대처 전략의 실제 작동 장면과 일치함."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/3"],
      "relevance": "내담자가 '계획표 만들 때 설레긴 하는데 손이 자동으로 움직이는 느낌'이라고 한 것은 새 계획표 작성으로 죄책감을 달래는 대처 전략과 연결되며, 상황 사례 3에서 교수 면담 후 바로 도서관 좌석을 등록했다가 첫날 나온 것이 같은 패턴임."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/situations/3"],
      "relevance": "내담자가 '예전에는 이번엔 다를까 싶어서 계획표라도 만들면 잠깐 설레는데 그 설렘이 몇 시간도 안 가서 무너지는 게 이제 놀랍지도 않다'고 한 것은 자기관리 장치를 시작했다가 2주를 넘기지 못하는 패턴과 일치하며, 상황 사례 3에서 도서관 좌석을 등록한 뒤 첫날 나온 것이 그 예시임."
    }
  ]
}

